Device jacobian is not called when QNode contains gates that need to be decomposed
When a QNode contains gates that are not natively supported on a device they are decomposed by PennyLane (which is great!). 

Unfortunately (for some reason I do not understand) `diff_method='device'` does no longer work for QNodes containing such gates as is demonstrated by the following example:
```python
import pennylane as qml
from pennylane.devices import DefaultQubit
from pennylane.operation import Operation
import numpy as np

class MyDev(DefaultQubit):
    @classmethod
    def capabilities(cls):
        capabilities = super().capabilities().copy()
        capabilities.update(
            provides_jacobian=True,
        )
        return capabilities

    def jacobian(self, operations_or_tape, observables=None, parameters=None):
        raise Exception("This exception signals that the device jacobian() was called")

class RYZ(Operation):
    num_params = 2
    num_wires = 1
    par_domain = "R"
    grad_method = "A"

    @staticmethod
    def _matrix(*params):
        theta, phi = params
        return qml.RZ._matrix(phi + np.pi) @ qml.RY._matrix(theta + np.pi / 2)

    @staticmethod
    def decomposition(theta, phi, wires):
        decomp_ops = [
            qml.RY(np.pi / 2, wires=wires),
            qml.RY(theta, wires=wires),
            qml.RZ(phi, wires=wires),
            qml.RZ(np.pi, wires=wires),
        ]
        return decomp_ops

@qml.qnode(MyDev(wires=2), diff_method='device')
def circuit(params):
    RYZ(params[0], params[1], wires=0) # with this commented the device jacobian is called also with PennyLane master
    qml.RY(params[0], wires=0)
    return qml.expval(qml.Hermitian(np.array([[1, 0], [0, 0]]), wires=0))

params = np.array([0.75916255, -2.16921113])
qml.jacobian(circuit)(params)
raise Exception("This line should not be reached as device jacobian() should have been called")
```
With PL 0.13.0 `MyDev.jacobian()` is called, as is expected. With master `MyDev.jacobian()` is not called and PL computes the jacobian in some other way. By commenting out the `RYZ(params[0], params[1], wires=0)`, and thereby removing the only gate that needs to be decomposed, the device `jacobian()` is called again.

In C# Both the Interface version and the Abstract version works, which is better?

/*Abstract*/

abstract class BaseClass
{
    public abstract bool Validate();
}

class A : BaseClass
{
    public string? Email { get; set; }
    public string? Password { get; set; }

    public override bool Validate()
    {
        if (string.IsNullOrEmpty(Email)) return false;
        if (string.IsNullOrEmpty(Password)) return false;
        return true;
    }
}

class B : A
{
    public string? Phone { get; set; }

    public override bool Validate()
    {
        if (base.Validate()) return false;
        if (string.IsNullOrEmpty(Phone)) return false;
        return true;
    }
}
static class C
{
    public static bool ValidateAccount(BaseClass account)
    {
        return account.Validate();
    }
}

class Program
{
    static void Main(string[] args)
    {
        var instance = new B();
        Console.WriteLine(C.ValidateAccount(instance));
    }
}

/*Interface*/

interface I
{
    public bool Validate();
}

class A : I
{
    public string? Email { get; set; }
    public string? Password { get; set; }

    public virtual bool Validate()
    {
        if (string.IsNullOrEmpty(Email)) return false;
        if (string.IsNullOrEmpty(Password)) return false;
        return true;
    }
}

class B : A
{
    public string? Phone { get; set; }

    public override bool Validate()
    {
        if (base.Validate()) return false;
        if (string.IsNullOrEmpty(Phone)) return false;
        return true;
    }
}
static class C
{
    public static bool ValidateAccount(I account)
    {
        return account.Validate();
    }
}

class Program
{
    static void Main(string[] args)
    {
        var instance = new B();
        Console.WriteLine(C.ValidateAccount(instance));
    }
}

