          detail: action.payload
        }];
        return {
          ...state,
          messages: messages,
        };
      }

    case actions.ActionTypes.GET_PID32:
      return {
        ...state,
        pid32: null,
        isLoading: true,
      };
    case actions.ActionTypes.GET_PID32_SUCCESS:
      return {
        ...state,
        pid32: action.payload,
        isLoading: false,
      };
    case actions.ActionTypes.GET_PID32_FAILED:
      let messages = [{
        severity: 'error',
        summary: 'Failed to perform action',
        detail: action.payload
      }];
      return {
        ...state,
        messages: messages,
        // selectedNitTable: null, TODO
        isLoading: false,
      };

    case actions.ActionTypes.UPDATE_ALL_PID32:
    case actions.ActionTypes.UPDATE_PID32:
      return {
        ...state,
        isSaving: true,
      };
    case actions.ActionTypes.UPDATE_PID32_SUCCESS:
      return {
        ...state,
        pid32: action.payload,
        isSaving: false,
        messages: [{
          severity: 'success',
          summary: 'Info Message',
          detail: 'Injector successfully updated'
        }]
      };
    case actions.ActionTypes.UPDATE_PID32_FAILED:
      return {
        ...state,
        isSaving: false,
        messages: [{
          severity: 'error',
          summary: 'Failed update action',
          detail: action.payload
        }],
      };


    case actions.ActionTypes.UPDATE_ALL_PID32_SUCCESS:
      const overridedPayload: OverridedPid32 = action.payload;
      const overridedStr = overridedPayload.overrided.map(pid32 => pid32.injectorId).join('\n, ');
      const pid32: Pid32 = overridedPayload.pid32;
      const detail = 'Updated injectors ' + pid32.injectorId + ', ' + overridedStr;
      return {
        ...state,
        pid32,
        isSaving: false,
        messages: [{
          severity: 'success',
          summary: 'Injector successfully updated',
          detail
        }]
      };
    case actions.ActionTypes.UPDATE_ALL_PID32_FAILED:
      return {
        ...state,
        isSaving: false,
        messages: [{
          severity: 'error',
          summary: 'Failed to update pid32',
          detail: action.payload
        }],
      }; 
    case actions.ActionTypes.UNSELECT_PID32:
      return {
        ...state,
        pid32: null,
      };

    default:
      return state;
  }
}

